 useEffect(()=>{let cancelled=false;supabase.auth.getUser().then(({data,error})=>{if(error||!data.user)throw Error('Sign in to load records.');draftKey.current='pcc-pending-'+data.user.id;return loadWorkspace()}).then(data=>{if(cancelled)return;const cloud=data.state||stateRef.current;if(data.state){validateState(data.state);setS(data.state)}lastSaved.current=workspaceFingerprint(cloud);let pending='';try{pending=localStorage.getItem(draftKey.current)||'';if(pending&&matchesCloudDraft(pending,cloud)){localStorage.removeItem(draftKey.current);pending=''}}catch{}setRecovery(pending);revision.current=data.revision;setSyncStatus(pending?'Review recovered drafts':'All changes saved');setLoaded(true)}).catch(e=>{if(cancelled)return;setSyncStatus('Connection unavailable');setMessage(e.message)});function readLocation(){const [route,query]=location.hash.slice(1).split('?'),q=new URLSearchParams(query);if(nav.some(n=>n[0]===route))setPage(route==='Income'?'Transactions':route);else setPage('Overview');setScope(q.get('scope')==='Personal'?'Personal':q.get('scope')==='Business'?'Business':'All');if(/^\d{4}-(0[1-9]|1[0-2])$/.test(q.get('month')||''))setMonth(q.get('month')!);setFilter(route==='Income'?'Income':q.get('filter')||'All');setSearch(q.get('search')||'');}readLocation();setNavigationReady(true);window.addEventListener('hashchange',readLocation);return()=>{cancelled=true;window.removeEventListener('hashchange',readLocation)}},[]);
 useEffect(()=>{if(!loaded||recovery||workspaceFingerprint(s)===lastSaved.current)return;try{if(draftKey.current)localStorage.setItem(draftKey.current,JSON.stringify(s))}catch{}setSyncStatus('Saving…');const timer=setTimeout(()=>{saveQueue.current=saveQueue.current.then(async()=>{if(saveBlocked.current)throw Error('Saving paused after an error. Export your pending changes before reloading.');revision.current=await saveWorkspace(s,revision.current);lastSaved.current=workspaceFingerprint(s);if(stateRef.current===s){setSyncStatus('All changes saved');if(pendingGoal.current){if(s.goals.some(g=>g.name===pendingGoal.current&&g.saved>=g.target))setGoalMoment(pendingGoal.current);pendingGoal.current=''}if(draftKey.current)localStorage.removeItem(draftKey.current)}}).catch(e=>{saveBlocked.current=true;setSyncStatus('Unsaved changes · export a backup');setMessage(e.message)})},350);return()=>clearTimeout(timer)},[s,loaded,recovery]);
