 const trend=Array.from({length:chartMonths},(_,i)=>{const [y,mo]=month.split('-').map(Number);const d=new Date(y,mo-chartMonths+i,1);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;return {month:d.toLocaleDateString('en-US',{month:'short'}),cash:scopedMetrics(s,scope,key).cash===null?null:scopedMetrics(s,scope,key).cash!/100}});
